import { describe, it, expect } from 'vitest';
import { verifyPasswordOrCode, hashPasswordOrCode } from '../src/utils/hash.utils.js';

describe('Password & Login-Code Hash Compatibility', () => {
  // Hash generated by Python Werkzeug scrypt:32768:8:1 for password 'Vedantdubey24@123'
  const werkzeugScryptHash =
    'scrypt:32768:8:1$U9ZV25TongDJw9tq$ab0fb82c45f7ad4659362cb5564db64184e0ed315b95922acc6a192dcd8b3afaeeea068cc6f46d704145a9f6352f0b8830aeec50c3a4203643c032d98d3a8f57';

  it('Successfully verifies legacy Werkzeug scrypt hash with correct password and flags needsRehash', async () => {
    const result = await verifyPasswordOrCode('Vedantdubey24@123', werkzeugScryptHash);
    expect(result.match).toBe(true);
    expect(result.needsRehash).toBe(true);
  });

  it('Rejects incorrect password against Werkzeug scrypt hash', async () => {
    const result = await verifyPasswordOrCode('IncorrectPassword', werkzeugScryptHash);
    expect(result.match).toBe(false);
    expect(result.needsRehash).toBe(false);
  });

  it('Successfully verifies standard bcrypt hash without needing rehash', async () => {
    const bcryptHash = await hashPasswordOrCode('SecurePassword123');
    const result = await verifyPasswordOrCode('SecurePassword123', bcryptHash);
    expect(result.match).toBe(true);
    expect(result.needsRehash).toBe(false);
  });

  it('Rejects incorrect password against bcrypt hash', async () => {
    const bcryptHash = await hashPasswordOrCode('SecurePassword123');
    const result = await verifyPasswordOrCode('WrongPassword', bcryptHash);
    expect(result.match).toBe(false);
    expect(result.needsRehash).toBe(false);
  });
});
